import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useStore } from '../store/useStore'
import StatCard from '../components/StatCard'
import PropertyCard from '../components/PropertyCard'
import PropertyModal from '../components/PropertyModal'
import BillModal from '../components/BillModal'
import { Building2, Users, DollarSign, AlertCircle, Plus, Calendar } from 'lucide-react'

export default function Home() {
  const navigate = useNavigate()
  const { properties, rooms, tenants, bills, addProperty, addBill } = useStore()
  const [showPropertyModal, setShowPropertyModal] = useState(false)
  const [showBillModal, setShowBillModal] = useState(false)

  const totalProperties = properties.length
  const totalRooms = rooms.length
  const occupiedRooms = rooms.filter(r => r.status === 'occupied').length
  const totalRentReceived = bills
    .filter(b => b.direction === 'receivable' && b.status === 'paid')
    .reduce((sum, b) => sum + b.amount, 0)
  const pendingBills = bills.filter(b => b.status === 'pending' || b.status === 'overdue')
  const recentProperties = properties.slice(0, 3)

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      <div className="bg-gradient-to-br from-blue-900 via-blue-800 to-blue-900 px-4 pt-10 pb-16">
        <div className="max-w-md mx-auto">
          <h1 className="text-2xl font-bold text-white mb-1">房屋管理</h1>
          <p className="text-blue-200 text-sm">轻松管理您的物业</p>
        </div>
      </div>

      <div className="px-4 -mt-10">
        <div className="max-w-md mx-auto">
          <div className="grid grid-cols-2 gap-3 mb-6">
            <StatCard
              title="楼栋总数"
              value={totalProperties}
              icon={Building2}
              color="blue"
            />
            <StatCard
              title="已出租"
              value={`${occupiedRooms}/${totalRooms}`}
              icon={Users}
              color="green"
            />
            <StatCard
              title="已收租金"
              value={`¥${totalRentReceived}`}
              icon={DollarSign}
              color="green"
            />
            <StatCard
              title="待处理账单"
              value={pendingBills.length}
              icon={AlertCircle}
              color={pendingBills.length > 0 ? 'orange' : 'blue'}
            />
          </div>

          {/* 提醒区域 */}
          {(() => {
            const unpaidReceivable = bills.filter(b => b.direction === 'receivable' && (b.status === 'pending' || b.status === 'overdue'))
            const unpaidPayable = bills.filter(b => b.direction === 'payable' && (b.status === 'pending' || b.status === 'overdue'))
            const expiringSoon = tenants.filter(t => {
              if (t.status !== 'active') return false
              const daysLeft = Math.ceil((new Date(t.contractEnd).getTime() - Date.now()) / (1000 * 60 * 60 * 24))
              return daysLeft >= 0 && daysLeft <= 30
            })
            const alerts = [
              unpaidReceivable.length > 0 && { icon: AlertCircle, color: 'text-red-600 bg-red-50', text: `${unpaidReceivable.length} 笔租客账单未收` },
              unpaidPayable.length > 0 && { icon: AlertCircle, color: 'text-orange-600 bg-orange-50', text: `${unpaidPayable.length} 笔房东账单未付` },
              expiringSoon.length > 0 && { icon: Calendar, color: 'text-yellow-600 bg-yellow-50', text: `${expiringSoon.length} 份合同即将到期` },
            ].filter(Boolean)
            
            return alerts.length > 0 ? (
              <div className="mb-6 space-y-2">
                {alerts.map((alert, i) => (
                  <div key={i} className={`flex items-center gap-2 px-4 py-3 rounded-xl text-sm font-medium ${alert.color}`}>
                    <alert.icon className="w-5 h-5" />
                    <span>{alert.text}</span>
                  </div>
                ))}
              </div>
            ) : null
          })()}

          <div className="mb-6">
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-lg font-semibold text-gray-900">我的楼栋</h2>
            </div>
            <div className="space-y-3">
              {recentProperties.map(property => (
                <PropertyCard
                  key={property.id}
                  property={property}
                  roomCount={rooms.filter(r => r.propertyId === property.id).length}
                  onClick={() => navigate(`/properties/${property.id}`)}
                />
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3 mb-6">
            <button
              type="button"
              onClick={() => setShowPropertyModal(true)}
              className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 flex flex-col items-center gap-2 hover:shadow-md transition-shadow cursor-pointer"
            >
              <div className="w-12 h-12 bg-blue-100 rounded-xl flex items-center justify-center">
                <Plus className="w-6 h-6 text-blue-600" />
              </div>
              <span className="text-sm font-medium text-gray-700">添加楼栋</span>
            </button>
            <button
              type="button"
              onClick={() => setShowBillModal(true)}
              className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 flex flex-col items-center gap-2 hover:shadow-md transition-shadow cursor-pointer"
            >
              <div className="w-12 h-12 bg-green-100 rounded-xl flex items-center justify-center">
                <Plus className="w-6 h-6 text-green-600" />
              </div>
              <span className="text-sm font-medium text-gray-700">添加账单</span>
            </button>
          </div>
        </div>
      </div>

      <PropertyModal
        isOpen={showPropertyModal}
        onClose={() => setShowPropertyModal(false)}
        onSave={(data) => {
          addProperty(data)
          setShowPropertyModal(false)
        }}
      />
      
      <BillModal
        isOpen={showBillModal}
        onClose={() => setShowBillModal(false)}
        onSave={(data) => {
          addBill(data)
          setShowBillModal(false)
        }}
        properties={properties}
        rooms={rooms}
        tenants={tenants}
      />
    </div>
  )
}
