import { useStore } from '../store/useStore'
import { Settings, HelpCircle, Database, Trash2, UserPlus, Calendar, Download, Upload } from 'lucide-react'
import { useRef } from 'react'

type MenuColor = 'blue' | 'green' | 'purple' | 'gray' | 'orange'

interface MenuItem {
  icon: React.ComponentType<{ className?: string }>
  label: string
  description: string
  color: MenuColor
}

const colorClasses: Record<MenuColor, string> = {
  blue: 'bg-blue-100 text-blue-600',
  green: 'bg-green-100 text-green-600',
  purple: 'bg-purple-100 text-purple-600',
  gray: 'bg-gray-100 text-gray-600',
  orange: 'bg-orange-100 text-orange-600',
}

const menuItems: MenuItem[] = [
  {
    icon: Calendar,
    label: '合同管理',
    description: '管理租赁合同',
    color: 'green'
  },
  {
    icon: Database,
    label: '数据备份',
    description: '备份您的数据',
    color: 'purple'
  },
  {
    icon: Settings,
    label: '设置',
    description: '应用设置',
    color: 'gray'
  },
  {
    icon: HelpCircle,
    label: '帮助与反馈',
    description: '获取帮助',
    color: 'orange'
  }
]

export default function More() {
  const { properties, tenants, bills, clearAllData } = useStore()
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleExport = () => {
    const data = localStorage.getItem('property-manager-data')
    if (!data) return
    const blob = new Blob([data], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `房屋管理数据_${new Date().toISOString().slice(0, 10)}.json`
    a.click()
    URL.revokeObjectURL(url)
  }

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = (ev) => {
      try {
        const json = JSON.parse(ev.target?.result as string)
        localStorage.setItem('property-manager-data', JSON.stringify(json))
        window.location.reload()
      } catch {
        alert('文件格式错误，请选择正确的备份文件')
      }
    }
    reader.readAsText(file)
    e.target.value = ''
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      <div className="bg-white border-b border-gray-100 px-4 pt-10 pb-6">
        <div className="max-w-md mx-auto">
          <h1 className="text-xl font-bold text-gray-900 mb-6">更多</h1>
          
          <div className="bg-gradient-to-br from-blue-900 to-blue-800 rounded-2xl p-5">
            <div className="flex items-center gap-4 mb-4">
              <div className="w-14 h-14 bg-white/20 rounded-2xl flex items-center justify-center">
                <UserPlus className="w-7 h-7 text-white" />
              </div>
              <div>
                <h2 className="text-lg font-semibold text-white">您的管理概览</h2>
                <p className="text-blue-200 text-sm">轻松管理您的房产</p>
              </div>
            </div>
            <div className="grid grid-cols-3 gap-3">
              <div className="bg-white/10 rounded-xl p-3 text-center">
                <p className="text-2xl font-bold text-white">{properties.length}</p>
                <p className="text-blue-200 text-xs">房屋</p>
              </div>
              <div className="bg-white/10 rounded-xl p-3 text-center">
                <p className="text-2xl font-bold text-white">{tenants.length}</p>
                <p className="text-blue-200 text-xs">租客</p>
              </div>
              <div className="bg-white/10 rounded-xl p-3 text-center">
                <p className="text-2xl font-bold text-white">{bills.length}</p>
                <p className="text-blue-200 text-xs">账单</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="px-4 pt-6">
        <div className="max-w-md mx-auto space-y-3">
          {menuItems.map((item, index) => {
            const Icon = item.icon
            
            return (
              <button
                key={index}
                type="button"
                onClick={(e) => {
                  e.preventDefault()
                  e.stopPropagation()
                  alert(`${item.label}功能开发中...`)
                }}
                className="w-full bg-white rounded-2xl shadow-sm border border-gray-100 p-4 flex items-center gap-4 hover:shadow-md transition-shadow cursor-pointer"
              >
                <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${colorClasses[item.color]}`}>
                  <Icon className="w-6 h-6" />
                </div>
                <div className="flex-1 text-left">
                  <p className="font-medium text-gray-900">{item.label}</p>
                  <p className="text-sm text-gray-500">{item.description}</p>
                </div>
                <div className="w-5 h-5 text-gray-300">
                  <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                  </svg>
                </div>
              </button>
            )
          })}
        </div>

        {/* 数据导入导出 */}
        <div className="max-w-md mx-auto mt-6 grid grid-cols-2 gap-3">
          <button
            type="button"
            onClick={handleExport}
            className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 flex flex-col items-center gap-2 hover:shadow-md transition-colors cursor-pointer"
          >
            <Download className="w-6 h-6 text-blue-600" />
            <span className="text-sm font-medium text-gray-700">导出数据</span>
          </button>
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 flex flex-col items-center gap-2 hover:shadow-md transition-colors cursor-pointer"
          >
            <Upload className="w-6 h-6 text-green-600" />
            <span className="text-sm font-medium text-gray-700">导入数据</span>
          </button>
        </div>
        <input
          ref={fileInputRef}
          type="file"
          accept=".json"
          onChange={handleImport}
          className="hidden"
        />

        <div className="max-w-md mx-auto mt-8">
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault()
              e.stopPropagation()
              if (confirm('确定要清除所有数据吗？此操作不可恢复！')) {
                clearAllData()
              }
            }}
            className="w-full bg-white rounded-2xl shadow-sm border border-red-100 p-4 flex items-center justify-center gap-3 text-red-600 hover:bg-red-50 transition-colors cursor-pointer"
          >
            <Trash2 className="w-5 h-5" />
            <span className="font-medium">清除所有数据</span>
          </button>
        </div>

        <div className="max-w-md mx-auto mt-8 text-center">
          <p className="text-sm text-gray-400">房屋管理 v1.0.0</p>
        </div>
      </div>
    </div>
  )
}
